// זמן היצירה של גלריה. גלריות חדשות שומרות createdAt מספרי; לישנות
// נופלים לפרסור של התאריך המוצג (d.m.yyyy מ-toLocaleDateString בעברית).
function photoAlbumTime(p) {
  if (!p) return 0;
  if (typeof p.createdAt === 'number' && isFinite(p.createdAt) && p.createdAt > 0) return p.createdAt;
  
  const idStr = String(p.id || '');
  const idDigits = idStr.replace(/\D/g, '');
  if (idDigits.length >= 10) {
    const parsedIdTime = parseInt(idDigits, 10);
    if (parsedIdTime && isFinite(parsedIdTime)) return parsedIdTime;
  }

  const str = String(p.timestamp || '').trim();
  const now = Date.now();
  const dayMs = 86400000;

  if (str.includes('היום')) {
    const timeMatch = str.match(/(\d{1,2}):(\d{2})/);
    if (timeMatch) {
      const d = new Date();
      d.setHours(Number(timeMatch[1]), Number(timeMatch[2]), 0, 0);
      return d.getTime();
    }
    return now;
  }
  if (str.includes('אתמול')) {
    const timeMatch = str.match(/(\d{1,2}):(\d{2})/);
    const d = new Date(now - dayMs);
    if (timeMatch) d.setHours(Number(timeMatch[1]), Number(timeMatch[2]), 0, 0);
    return d.getTime();
  }
  if (str.includes('לפני יומיים')) return now - 2 * dayMs;
  if (str.includes('לפני 3 ימים')) return now - 3 * dayMs;
  if (str.includes('השבוע') || str.includes('לפני שבוע') || str.includes('עודכן השבוע')) return now - 5 * dayMs;
  if (str.includes('לפני שבועיים')) return now - 14 * dayMs;
  if (str.includes('החודש') || str.includes('לפני חודש')) return now - 25 * dayMs;
  if (str.includes('השנה')) return now - 120 * dayMs;

  const m = str.match(/(\d{1,2})[.\/-](\d{1,2})[.\/-](\d{4})/);
  if (m) {
    const t = new Date(Number(m[3]), Number(m[2]) - 1, Number(m[1])).getTime();
    if (isFinite(t)) return t;
  }

  const fallbackIdNum = parseInt(idDigits, 10);
  return fallbackIdNum || 0;
}

// גבול תחתון לפי לוח השנה, כדי שהתוויות יהיו נכונות מילולית:
// "השבוע" מתחילת השבוע הנוכחי, "החודש" מה-1 בחודש, "השנה" מ-1 בינואר.
function photoDateThreshold(range) {
  const now = new Date();
  if (range === 'השבוע') {
    const d = new Date(now.getFullYear(), now.getMonth(), now.getDate());
    d.setDate(d.getDate() - d.getDay()); // ראשון הוא תחילת השבוע
    return d.getTime();
  }
  if (range === 'החודש') return new Date(now.getFullYear(), now.getMonth(), 1).getTime();
  if (range === 'השנה') return new Date(now.getFullYear(), 0, 1).getTime();
  return null;
}

function photoSetFilter(kind, value) {
  const isStories = (typeof pfActivePage === 'function' && pfActivePage() === 'stories');
  if (isStories) {
    if (kind === 'general') currentStoryGeneralFilter = value;
  } else {
    if (kind === 'general') currentPhotoGeneralFilter = value;
  }
  // מין / מיקום / תאריך / גיל: מצב אחד משותף לשורה העליונה ולפאנל הצד
  if (kind === 'category' || kind === 'region' || kind === 'date') {
    photoSel[kind] = (value === 'הכל') ? [] : [value];
  } else if (kind === 'age') {
    const b = (value === 'הכל') ? null : photoAgeBucket(value);
    photoAgeMin = b ? b[0] : 18;
    photoAgeMax = b ? b[1] : 99;
  }

  // אחרי בחירה סוגרים וחוזרים לשלושת הכפתורים. הרינדור מחליף את
  // הסרגל כולו, ולכן אין טעם לגעת ב-classList של הכפתור שנלחץ.
  photoOpenFilterGroup = null;
  photoRenderFilterBar();
  if (typeof pfApplyActive === 'function') pfApplyActive();
  else photoApplyFilters();
}
window.photoSetFilter = photoSetFilter;

// נשמר לתאימות אחורה עם קריאות ישנות
function photoFilterCategory(category) {
  photoSetFilter('category', category);
}
window.photoFilterCategory = photoFilterCategory;

// מיון "כללי": האחרונים / הפופולארים / הישנים. משנה את סדר הכרטיסים
// בכל מקטע (.art-rows) בעמוד התמונות. "הכל" מחזיר לסדר המקורי של הבנייה.
function photoApplySort() {
  // ממיין את העמוד הפעיל בלבד, לפי מצב המיון שלו
  const stories = (typeof pfActivePage === 'function' && pfActivePage() === 'stories');
  const mode = stories ? currentStoryGeneralFilter : currentPhotoGeneralFilter;
  const containers = mainContent.querySelectorAll(stories ? '.stories-page .art-rows' : '.photos-page .art-rows');
  containers.forEach(container => {
    const rows = Array.from(container.children).filter(el => el.classList && el.classList.contains('art-row'));
    if (!rows.length) return;
    // חותמים את הסדר המקורי פעם אחת כדי שנוכל לשחזר אותו ב"הכל"
    rows.forEach((r, i) => { if (r.dataset.origIndex === undefined) r.dataset.origIndex = String(i); });

    const num = (r, attr) => Number(r.dataset[attr]) || 0;
    let sorted;
    if (mode === 'האחרונים')       sorted = rows.slice().sort((a, b) => num(b, 'time') - num(a, 'time'));
    else if (mode === 'הישנים')    sorted = rows.slice().sort((a, b) => num(a, 'time') - num(b, 'time'));
    else if (mode === 'הפופולארים') sorted = rows.slice().sort((a, b) => num(b, 'score') - num(a, 'score'));
    else                            sorted = rows.slice().sort((a, b) => num(a, 'origIndex') - num(b, 'origIndex'));

    sorted.forEach(r => container.appendChild(r));
  });
}

// ===== תגיות (#) וסינון — שורת כלים בעמוד התמונות; במובייל הסינון נפתח במסך מלא =====
var photoHashtag = '';
const HASHTAG_RE = /#([\p{L}\p{N}_]{2,30})/gu;
function photoHashtagCounts() {
  const counts = {};
  ((typeof photoGetAlbums === 'function') ? photoGetAlbums() : []).forEach(a => {
    if (!a || a.approved === false) return;
    const seen = new Set();
    for (const m of `${a.title || ''} ${a.summary || ''}`.matchAll(HASHTAG_RE)) {
      const t = m[1].toLowerCase();
      if (!seen.has(t)) { seen.add(t); counts[t] = (counts[t] || 0) + 1; }
    }
  });
  return Object.entries(counts).sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]));
}
function photoActiveFilterCount() {
  let n = (photoSel.category.length + photoSel.region.length + photoSel.date.length);
  if (typeof currentPhotoGeneralFilter !== 'undefined' && ['הפופולארים', 'הישנים'].includes(currentPhotoGeneralFilter)) n++;
  return n;
}
function photoToolsRowHTML() {
  const n = photoActiveFilterCount();
  return `<div class="m-tools">
      <button type="button" class="m-tool${photoHashtag ? ' on' : ''}" onclick="openHashtagSheet()" aria-label="תגיות" title="תגיות">
        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round"><path d="M9 3 7 21M17 3l-2 18M4 8.5h17M3 15.5h17"/></svg>
      </button>
      <button type="button" class="m-tool m-tool-filter" onclick="openFilterSheet()" aria-label="סינון" title="סינון">
        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round"><path d="M4 6h16M4 12h16M4 18h16"/><circle cx="15" cy="6" r="2.2" fill="var(--mt-bg,#492b3c)"/><circle cx="9" cy="12" r="2.2" fill="var(--mt-bg,#492b3c)"/><circle cx="15" cy="18" r="2.2" fill="var(--mt-bg,#492b3c)"/></svg>
        ${n ? `<span class="m-tool-badge">${n}</span>` : ''}
      </button>
      ${photoHashtag ? `<button type="button" class="m-tag-chip" onclick="setPhotoHashtag('')">#${escHtml(photoHashtag)} <span aria-hidden="true">✕</span></button>` : ''}
    </div>`;
}
function photoRefreshTools() {
  document.querySelectorAll('.m-tools').forEach(el => { el.outerHTML = photoToolsRowHTML(); });
}
function setPhotoHashtag(tag) {
  photoHashtag = String(tag || '').toLowerCase();
  closeMSheet();
  photoApplyFilters();
  photoRefreshTools();
  const list = mainContent.querySelector('.photo-section-row');
  if (photoHashtag && list) list.scrollIntoView({ behavior: 'smooth', block: 'start' });
}
window.setPhotoHashtag = setPhotoHashtag;

// חלון "גיליון": במובייל מסך מלא עם חץ חזרה; במחשב חלון במרכז
function openMSheet(title, bodyHTML, footHTML) {
  let el = document.getElementById('m-sheet');
  if (!el) { el = document.createElement('div'); el.id = 'm-sheet'; document.body.appendChild(el); }
  el.innerHTML = `
    <div class="ms-backdrop" onclick="closeMSheet()"></div>
    <div class="ms-panel" role="dialog" aria-label="${escHtml(title)}">
      <header class="ms-head">
        <span class="ms-title">${escHtml(title)}</span>
        <button type="button" class="ms-back ms-x" onclick="closeMSheet()" aria-label="סגירה"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M18 6 6 18M6 6l12 12"/></svg></button>
      </header>
      <div class="ms-body">${bodyHTML}</div>
      ${footHTML ? `<footer class="ms-foot">${footHTML}</footer>` : ''}
    </div>`;
  document.documentElement.classList.add('ms-open');
  requestAnimationFrame(() => el.classList.add('show'));
}
function closeMSheet() {
  const el = document.getElementById('m-sheet');
  document.documentElement.classList.remove('ms-open');
  if (el) { el.classList.remove('show'); el.innerHTML = ''; }
}
window.closeMSheet = closeMSheet;

function openHashtagSheet() {
  const tags = photoHashtagCounts();
  const body = tags.length
    ? `<div class="ms-tags">${tags.map(([t, n]) => `<button type="button" class="ms-tag${t === photoHashtag ? ' on' : ''}" onclick="setPhotoHashtag('${artEsc(t)}')">#${escHtml(t)}<b>${n}</b></button>`).join('')}</div>`
    : `<div class="ms-empty">עדיין אין תגיות.<br>כשמעלים גלריה אפשר לכתוב בתיאור למשל <b>#חוף</b> או <b>#זוגות</b> — והתגית תופיע כאן.</div>`;
  openMSheet('תגיות', body, photoHashtag ? `<button type="button" class="ms-btn ghost" onclick="setPhotoHashtag('')">ביטול התגית #${escHtml(photoHashtag)}</button>` : '');
}
window.openHashtagSheet = openHashtagSheet;

// סינון בסגנון X: שורות "שם · ערך ›" שנפתחות לבחירה, מתגים, ובתחתית "איפוס" ו"הצגת תוצאות"
function fsIsShop() { return !!(typeof mainContent !== 'undefined' && mainContent && mainContent.querySelector('.secondhand-page')); }
function filterSheetBodyHTML() {
  const open = window.__fsOpen || '';
  const shop = fsIsShop();
  const sortRaw = (typeof currentPhotoGeneralFilter !== 'undefined' && currentPhotoGeneralFilter) || '';
  const sortNow = ['האחרונים', 'הפופולארים', 'הישנים'].includes(sortRaw) ? sortRaw : 'האחרונים';
  const sortLbl = { 'האחרונים': 'החדשים ביותר', 'הפופולארים': 'הכי פופולרי', 'הישנים': 'הישנים ביותר' };
  const chev = '<svg class="fs-chev" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M15 6l-6 6 6 6"/></svg>';
  const row = (key, label, value, optsHTML) => `<div class="fs-row${open === key ? ' open' : ''}">
      <button type="button" class="fs-row-head" onclick="fsToggleRow('${key}')"><span class="fs-label">${label}</span><span class="fs-val">${escHtml(value)}</span>${chev}</button>
      ${open === key ? `<div class="fs-opts">${optsHTML}</div>` : ''}
    </div>`;
  const radio = (on, act, label, ic) => `<button type="button" class="fs-opt${on ? ' on' : ''}" onclick="${act}">${ic ? `<svg class="fs-opt-ic" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round">${ic}</svg>` : ''}<span>${escHtml(label)}</span><i>${on ? '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"><path d="M5 12.5l4.5 4.5L19 7.5"/></svg>' : ''}</i></button>`;
  const sortIc = { 'האחרונים': '<circle cx="12" cy="12" r="8.5"/><path d="M12 7.5V12l3 2"/><path d="M16.5 3.5 19 6"/>', 'הפופולארים': '<path d="M12 3c.7 3.6 4.5 5.1 4.5 9.5a4.5 4.5 0 0 1-9 0c0-1.8.9-3.1 1.8-4.1.3 1.5 1.1 2.4 2.1 2.6C11.2 8.6 11 5.7 12 3z"/>', 'הישנים': '<circle cx="12" cy="12" r="8.5"/><path d="M12 7.5V12l-3 2"/>' };
  const multiVal = kind => photoSel[kind].length ? photoSel[kind].join(', ') : 'הכל';
  const multi = (kind, list) => list.filter(v => v !== 'הכל').map(v => radio(photoSel[kind].includes(v), `filterSheetToggle('${kind}','${artEsc(v)}',${!photoSel[kind].includes(v)})`, v)).join('');
  const tgl = (label, on, act) => `<label class="fs-toggle"><span>${label}</span><span class="tgl-switch"><input type="checkbox" ${on ? 'checked' : ''} onchange="${act}"><span class="tgl-slider"></span></span></label>`;
  const sortRow = row('sort', 'מיון', sortLbl[sortNow], ['האחרונים', 'הפופולארים', 'הישנים'].map(v => radio(sortNow === v, `filterSheetSort('${artEsc(v)}')`, sortLbl[v], sortIc[v])).join(''));
  if (shop) {
    const shRow = (key, label, cur, list) => row(key, label, cur, list.map(v => radio(cur === v, `setShFilter('${key}','${artEsc(v)}'); if (typeof pfRefreshShBar === 'function') pfRefreshShBar(); filterSheetRefresh()`, v)).join(''));
    return sortRow
      + shRow('offer', 'סוג ההצעה', shOfferFilter, SH_OFFER_TYPES)
      + `<div class="fs-slider"><div class="fs-slider-head"><span class="fs-label">טווח מחירים</span></div>${dualSliderHTML('price')}</div>`
      + shRow('region', 'מיקום', shRegionFilter, SH_REGIONS)
      + tgl('הפעלת מיקום', !!shLocationEnabled, 'toggleShLocation(this.checked)');
  }
  return sortRow
    + `<div class="fs-slider"><div class="fs-slider-head"><span class="fs-label">טווח גילאים</span></div>${dualSliderHTML('age')}</div>`
    + row('category', 'מין', multiVal('category'), multi('category', PHOTO_CATEGORIES))
    + row('region', 'אזור', multiVal('region'), multi('region', PHOTO_REGIONS))
    + row('date', 'תאריך העלאה', multiVal('date'), multi('date', PHOTO_DATE_RANGES))
    + tgl('משתמשים מאומתים בלבד', !!photoVerifiedOnly, 'photoToggleVerified(!this.checked); filterSheetRefresh()')
    + tgl('קרוב אליי', !!userMapMe, 'photoToggleLocation(!this.checked)');
}
function fsToggleRow(k) { window.__fsOpen = window.__fsOpen === k ? '' : k; filterSheetRefresh(); }
window.fsToggleRow = fsToggleRow;
function filterSheetVisibleCount() {
  if (fsIsShop()) return [...mainContent.querySelectorAll('.secondhand-page .art-row')].filter(r => getComputedStyle(r).display !== 'none' && r.dataset.artMatch !== '0').length;
  return [...mainContent.querySelectorAll('.photos-page[data-section="photos"] .art-row')].filter(r => r.dataset.artMatch !== '0').length;
}
function filterSheetFootHTML() {
  return `<button type="button" class="ms-btn ghost fs-reset" onclick="filterSheetClear()">איפוס</button>
    <button type="button" class="ms-btn fs-go" onclick="closeMSheet()">הצגת ${filterSheetVisibleCount()} תוצאות</button>`;
}
function filterSheetRefresh() {
  const body = document.querySelector('#m-sheet .ms-body'), foot = document.querySelector('#m-sheet .ms-foot');
  if (body) { const y = body.scrollTop; body.innerHTML = filterSheetBodyHTML(); body.scrollTop = y; }
  if (foot) foot.innerHTML = filterSheetFootHTML();
  photoRefreshTools();
}
function openFilterSheet() {
  window.__fsOpen = '';
  openMSheet('סינון', filterSheetBodyHTML(), filterSheetFootHTML());
  const sh = document.getElementById('m-sheet'); if (sh) sh.classList.add('fs-x');
}
window.openFilterSheet = openFilterSheet;
function filterSheetToggle(kind, value, checked) { photoToggleMulti(kind, value, checked); filterSheetRefresh(); }
window.filterSheetToggle = filterSheetToggle;
function filterSheetSort(value) { photoSetSort(value, { closest: () => null, checked: true }); filterSheetRefresh(); }
window.filterSheetSort = filterSheetSort;
function filterSheetClear() {
  if (fsIsShop()) { ['offer', 'price', 'region'].forEach(k => setShFilter(k, 'הכל')); if (typeof pfRefreshShBar === 'function') pfRefreshShBar(); }
  photoSel.category.length = 0; photoSel.region.length = 0; photoSel.date.length = 0;
  photoSetSort('האחרונים', { closest: () => null, checked: true });
  filterSheetRefresh();
}
window.filterSheetClear = filterSheetClear;
document.addEventListener('keydown', (e) => { if (e.key === 'Escape' && document.documentElement.classList.contains('ms-open')) closeMSheet(); });

function photoApplyFilters() {
  photoApplySort();
  const searchInput = mainContent.querySelector('.photos-page .art-search');
  const q = searchInput ? searchInput.value.toLowerCase().trim() : '';
  
  const rows = mainContent.querySelectorAll('.photos-page .art-row');
  const isAgeVerified = typeof sessionStorage !== 'undefined' && sessionStorage.getItem('age_verified') === 'true';
  const ageActive = (photoAgeMin > 18 || photoAgeMax < 99);
  // אילוצי שורת-הצ׳יפים העליונה (בחירה יחידה). התוצאה היא חיתוך (AND)
  // של שורת הצ׳יפים עם פאנל הצד — שתי מערכות הסינון פועלות יחד.
  const topDateThreshold = photoDateThreshold(currentPhotoDateFilter);
  let visible = 0;

  rows.forEach(r => {
    const rowCategory = r.dataset.category || 'כללי';
    // הכרטיס מציג רק תמונה, ולכן מחפשים בתכונת data-search ולא בטקסט הגלוי
    const text = (r.dataset.search || r.textContent).toLowerCase();

    const rowRegion = r.dataset.region || '';
    const rowAge = r.dataset.age || '';
    const rowTime = r.dataset.time ? Number(r.dataset.time) : null;

    // מין — פאנל הצד (בחירה מרובה) AND שורת הצ׳יפים (בחירה יחידה)
    const categoryMatch =
      (!photoSel.category.length || photoSel.category.includes(rowCategory)) &&
      (currentPhotoCategoryFilter === 'הכל' || rowCategory === currentPhotoCategoryFilter);

    // מיקום — פאנל הצד AND שורת הצ׳יפים
    const regionMatch =
      (!photoSel.region.length || photoSel.region.includes(rowRegion)) &&
      (currentPhotoRegionFilter === 'הכל' || rowRegion === currentPhotoRegionFilter);

    // תאריך — פאנל הצד (OR על הטווחים שנבחרו) AND שורת הצ׳יפים
    const dateMatchSide = (!photoSel.date.length) || photoSel.date.some(dr => {
      const th = photoDateThreshold(dr);
      return th === null ? true : (rowTime !== null && rowTime >= th);
    });
    const dateMatchTop = (topDateThreshold === null) || (rowTime !== null && rowTime >= topDateThreshold);
    const dateMatch = dateMatchSide && dateMatchTop;

    // גיל — טווח שתי-הידיות בפאנל הצד AND בורר הגיל בשורת הצ׳יפים
    let ageMatch = true;
    if (ageActive) {
      const b = photoAgeBucket(rowAge);
      ageMatch = b ? (b[1] >= photoAgeMin && b[0] <= photoAgeMax) : false;
    }
    if (currentPhotoAgeFilter !== 'הכל') {
      const tb = photoAgeBucket(currentPhotoAgeFilter);
      const rb = photoAgeBucket(rowAge);
      ageMatch = ageMatch && !!(tb && rb && rb[1] >= tb[0] && rb[0] <= tb[1]);
    }

    const textMatch = text.includes(q);
    const isVerifiedRow = (r.dataset.verified === '1' || r.dataset.verified === 'true');
    const verifiedMatch = !photoVerifiedOnly || isVerifiedRow;

    const tagMatch = !photoHashtag || text.includes('#' + photoHashtag);
    const show = categoryMatch && ageMatch && regionMatch && dateMatch && textMatch && verifiedMatch && tagMatch;
    // העימוד הוא זה שקובע display בפועל; כאן רק מסמנים מה תואם
    r.dataset.artMatch = show ? '1' : '0';
    if (show) visible++;

    // הטשטוש של תוכן 18+ מנוהל כולו ע"י CSS (html.age-not-verified + data-adult),
    // ולכן כאן רק מנקים סגנון inline ישן כדי לא להתנגש.
    const imgWrap = r.querySelector('.art-row-img-wrap');
    if (imgWrap) {
      imgWrap.style.filter = '';
      imgWrap.style.removeProperty('-webkit-filter');
      const adult = r.dataset.adult === '1';
      imgWrap.title = (adult && !isAgeVerified) ? 'תוכן 18+ מטושטש - יש לאשר גיל בסרגל הצד' : '';
    }
  });

  // כל שינוי בחיפוש או בקטגוריה מחזיר לעמוד הראשון של התוצאות
  artPageState.photos = 1;
  artSyncPagination();

  const noResults = mainContent.querySelector('.photos-page .art-no-results');
  if (noResults) noResults.style.display = visible === 0 ? 'block' : 'none';
}
window.photoApplyFilters = photoApplyFilters;

