Object.assign(window, { forumAdminEdit, forumAdminRemove, forumAdminAdd, forumAdminEditTopic, forumAdminDeleteTopic, forumAdminEditPost, questionAdminEdit, questionAdminDelete });


// ============================================================
// "הודעה" בכרטיס: שליחת הודעה פרטית למי שהעלה — גם אם העלה כאורח.
// פריט ישן בלי חשבון מקושר — ההודעה מגיעה למנהל האתר, שמעביר אותה.
// ============================================================
function cardMsgBtnHTML(x) {
  if (!x) return '';
  return `<button type="button" class="art-telegram-btn art-msg-btn" onclick="event.stopPropagation(); messageUploader('${artEsc(x.id || '')}', '${artEsc(x.title || '')}', '${artEsc(x.authorId || '')}', '${artEsc(x.author || '')}')" title="הודעה למעלה" aria-label="הודעה למעלה"><svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round" style="display:block"><path d="M21 12a8 8 0 0 1-11.6 7.1L4 20l1-4.6A8 8 0 1 1 21 12z"/></svg></button>`;
}
async function messageUploader(id, title, authorId, author) {
  const t = String(title || '').slice(0, 100);
  if (authorId) {
    return dmStartWith(authorId, author || 'משתמש', t ? `שלום! לגבי "${t}": ` : 'שלום! ');
  }
  // אין חשבון מקושר — שולחים למנהל האתר עם פרטי הפריט
  let a = (typeof siteAdminUid === 'function') ? siteAdminUid() : '';
  if (!a) { try { const snap = await get(ref(db, 'website/admin_uid')); a = snap.val() || ''; if (a) localStorage.setItem('site_admin_uid', a); } catch (e) {} }
  if (!a) { if (typeof showCopyToast === 'function') showCopyToast('לא ניתן לשלוח הודעה כרגע'); return; }
  if (typeof showCopyToast === 'function') showCopyToast('מי שהעלה פרסם כאורח — ההודעה תגיע למנהל האתר שיעביר אותה');
  return dmStartWith(a, 'מנהל האתר', `הודעה עבור ${author || 'מי שהעלה'} — לגבי "${t}" (מזהה ${id}): `);
}
window.messageUploader = messageUploader;


// תיבת ההודעה בשיחה מתרחבת לפי הטקסט (עד ~6 שורות, אחר כך נגללת)
function dmAutoGrow(el) {
  if (!el) return;
  el.style.height = 'auto';
  el.style.height = Math.min(el.scrollHeight + 2, 150) + 'px';
}
window.dmAutoGrow = dmAutoGrow;


// ============================================================
// תקנון השאלה + חתימה דיגיטלית (השואל חותם בעמוד המוצר)
// website/loan_signatures/{itemId}/{uid} = { name, at, sig }
// ============================================================
function loanAgreementHTML(a) {
  const terms = (Array.isArray(a.loanTerms) && a.loanTerms.length) ? a.loanTerms : PHOTO_LOAN_DEFAULT_TERMS;
  setTimeout(() => loanSigInit(a), 0);
  return `<details class="loan-agr" id="loan-agr">
    <summary><b>תקנון ההשאלה</b><small>${terms.length} סעיפים · חתימה</small></summary>
    <ol class="loan-terms">${terms.map(t => `<li>${escHtml(t)}</li>`).join('')}</ol>
    <div class="loan-sign" id="loan-sign">
      <div class="loan-sign-head">חתימה על התקנון</div>
      <input id="loan-sign-name" class="loan-sign-name" maxlength="60" placeholder="שם מלא">
      <div class="loan-pad-wrap"><canvas id="loan-pad" class="loan-pad" width="600" height="180" aria-label="חתמו כאן"></canvas><span class="loan-pad-hint">חתמו כאן באצבע או בעכבר</span><button type="button" class="loan-pad-clear" onclick="loanSigClear()">ניקוי</button></div>
      <label class="loan-agree"><input type="checkbox" id="loan-agree"><span>קראתי את כל הסעיפים ואני מסכים/ה להם</span></label>
      <button type="button" class="pd2-offer-btn loan-sign-btn" onclick="loanSigSubmit('${artEsc(a.id)}', '${artEsc(a.title || '')}', '${artEsc(a.authorId || '')}', '${artEsc(a.author || '')}')">חתימה ושליחה למשאיל</button>
    </div>
  </details>`;
}
let loanPadDirty = false;
function loanSigInit(a) {
  const c = document.getElementById('loan-pad'); if (!c || c.dataset.ready) return;
  c.dataset.ready = '1';
  const ctx = c.getContext('2d');
  ctx.lineWidth = 3.2; ctx.lineCap = 'round'; ctx.lineJoin = 'round'; ctx.strokeStyle = '#111111';
  let drawing = false;
  const pos = e => { const r = c.getBoundingClientRect(); const t = e.touches ? e.touches[0] : e; return { x: (t.clientX - r.left) * (c.width / r.width), y: (t.clientY - r.top) * (c.height / r.height) }; };
  const start = e => { drawing = true; const p = pos(e); ctx.beginPath(); ctx.moveTo(p.x, p.y); e.preventDefault(); };
  const move = e => { if (!drawing) return; const p = pos(e); ctx.lineTo(p.x, p.y); ctx.stroke(); loanPadDirty = true; c.parentElement.classList.add('signed'); e.preventDefault(); };
  const end = () => { drawing = false; };
  c.addEventListener('mousedown', start); c.addEventListener('mousemove', move); window.addEventListener('mouseup', end);
  c.addEventListener('touchstart', start, { passive: false }); c.addEventListener('touchmove', move, { passive: false }); c.addEventListener('touchend', end);
  // כבר חתמתי? מציגים אישור במקום הטופס
  const u = auth.currentUser;
  if (u && a && a.id) {
    get(ref(db, `website/loan_signatures/${a.id}/${u.uid}`)).then(snap => {
      const v = snap.val(); if (!v) return;
      const box = document.getElementById('loan-sign');
      if (box) box.innerHTML = `<div class="loan-signed">✓ חתמת על התקנון ב-${escHtml(new Date(v.at).toLocaleDateString('he-IL'))} בשם <b>${escHtml(v.name || '')}</b></div>`;
    }).catch(() => {});
  }
}
function loanSigClear() {
  const c = document.getElementById('loan-pad'); if (!c) return;
  c.getContext('2d').clearRect(0, 0, c.width, c.height); loanPadDirty = false; c.parentElement.classList.remove('signed');
}
async function loanSigSubmit(id, title, lenderUid, lenderName) {
  const name = String((document.getElementById('loan-sign-name') || {}).value || '').trim();
  if (name.length < 2) { showCopyToast('נא לכתוב שם מלא'); return; }
  if (!loanPadDirty) { showCopyToast('נא לחתום בתיבת החתימה'); return; }
  if (!(document.getElementById('loan-agree') || {}).checked) { showCopyToast('נא לאשר שקראת את הסעיפים'); return; }
  if (!auth.currentUser) { const ok = (typeof ensureGuestSignedIn === 'function') ? await ensureGuestSignedIn() : false; if (!ok) { openLiveChatLogin(); return; } }
  const u = auth.currentUser;
  const c = document.getElementById('loan-pad');
  let sig = '';
  try {
    // חתימה מוקטנת — כדי לשמור במסד
    const t = document.createElement('canvas'); t.width = 300; t.height = 90;
    const tc = t.getContext('2d'); tc.fillStyle = '#ffffff'; tc.fillRect(0, 0, 300, 90); tc.drawImage(c, 0, 0, 300, 90);
    sig = t.toDataURL('image/jpeg', 0.7);
  } catch (e) {}
  try {
    await set(ref(db, `website/loan_signatures/${id}/${u.uid}`), { name: name.slice(0, 60), at: Date.now(), sig: sig.length < 60000 ? sig : '' });
    const box = document.getElementById('loan-sign');
    if (box) box.innerHTML = `<div class="loan-signed">✓ חתמת על התקנון בשם <b>${escHtml(name)}</b> — המשאיל קיבל הודעה</div>`;
    showCopyToast('החתימה נשמרה ונשלחה למשאיל');
    if (lenderUid && lenderUid !== u.uid) offerRecord({ kind: 'loan', toUid: lenderUid, toName: lenderName, itemId: id, title, price: 0, note: 'חתם/ה על תקנון ההשאלה בשם ' + name });
    if (lenderUid && lenderUid !== u.uid && typeof dmStartWith === 'function') {
      dmStartWith(lenderUid, lenderName || 'משאיל', `✍️ חתמתי על תקנון ההשאלה של "${String(title || '').slice(0, 80)}" בשם ${name}. אשמח לתאם איסוף.`);
    }
  } catch (e) { console.error(e); showCopyToast('לא הצלחנו לשמור את החתימה — נסו שוב'); }
}
Object.assign(window, { loanSigClear, loanSigSubmit });


// יד שניה: מסנכרנים את שורת הסינון העליונה (בפלאפון) עם הסינון בצד
function pfRefreshShBar() {
  const bar = document.querySelector('.sh-top') || document.querySelector('.sh-filter-bar');
  if (bar && typeof secondhandFilterBarHTML === 'function') bar.outerHTML = secondhandFilterBarHTML();
}
window.pfRefreshShBar = pfRefreshShBar;


// ============================================================
// מרכז ההצעות + התמקחות: כל הצעה היא רשומה משותפת לשני הצדדים
// website/offers/{id} = { kind, itemId, title, price, note, fromUid, fromName, toUid, toName, at,
//                         status: pending|counter|accepted|rejected|signed, lastBy, history: [...] }
// website/offers_idx/{uid}/{id} = true  (רשימת ההצעות של כל משתמש)
// ============================================================
var offersMap = {}, offersSubUid = '', offersItemUnsubs = {};
var OFFER_ST = {
  pending: { cls: 'wait', ic: '●', label: 'ממתין לתשובה' },
  counter: { cls: 'wait', ic: '●', label: 'הצעה נגדית' },
  accepted: { cls: 'ok', ic: '✓', label: 'אושר' },
  rejected: { cls: 'no', ic: '✕', label: 'נדחה' },
  signed: { cls: 'ok', ic: '✓', label: 'נחתם' }
};
async function offerRecord(o) {
  try {
    if (!auth.currentUser && typeof ensureGuestSignedIn === 'function') await ensureGuestSignedIn();
    const u = auth.currentUser; if (!u || !o.toUid) return;
    const id = push(ref(db, 'website/offers')).key;
    const fromName = (typeof liveChatUserName === 'function' && liveChatUserName()) || u.displayName || 'אורח';
    const now = Date.now();
    const status = o.kind === 'loan' ? 'signed' : 'pending';
    const rec = { kind: o.kind || 'price', itemId: String(o.itemId || '').slice(0, 80), title: String(o.title || '').slice(0, 120), price: Number(o.price) || 0,
      note: String(o.note || '').slice(0, 300), fromUid: u.uid, fromName: String(fromName).slice(0, 60), toUid: o.toUid, toName: String(o.toName || '').slice(0, 60),
      at: now, status, lastBy: u.uid, updatedAt: now,
      history: [{ by: u.uid, name: String(fromName).slice(0, 60), action: o.kind === 'loan' ? 'signed' : 'offer', price: Number(o.price) || 0, note: String(o.note || '').slice(0, 300), at: now }] };
    await set(ref(db, `website/offers/${id}`), rec);
    await set(ref(db, `website/offers_idx/${u.uid}/${id}`), true);
    await set(ref(db, `website/offers_idx/${o.toUid}/${id}`), true);
  } catch (e) { console.warn('offer record failed', e); }
}
function offersSubscribe() {
  const u = auth.currentUser;
  if (!u || offersSubUid === u.uid) return;
  offersSubUid = u.uid;
  try {
    onValue(ref(db, `website/offers_idx/${u.uid}`), snap => {
      const ids = Object.keys(snap.val() || {});
      ids.forEach(id => {
        if (offersItemUnsubs[id]) return;
        offersItemUnsubs[id] = onValue(ref(db, `website/offers/${id}`), s2 => {
          const v = s2.val();
          if (v) offersMap[id] = Object.assign({ id }, v); else delete offersMap[id];
          offersBadge(); offersRerender();
        }, () => {});
      });
      offersBadge(); offersRerender();
    }, () => {});
  } catch (e) {}
}
function offersMyTurn(o) {
  const u = auth.currentUser;
  return !!(u && o && (o.status === 'pending' || o.status === 'counter') && o.lastBy !== u.uid);
}
function offersBadge() {
  const b = document.getElementById('offers-badge'); if (!b) return;
  const n = Object.values(offersMap).filter(offersMyTurn).length;   // הצעות שמחכות לתשובה שלי
  b.textContent = n > 9 ? '9+' : String(n); b.style.display = n ? '' : 'none';
}
var offersTab = 'in';
function ofpListHTML() {
  const u = auth.currentUser, me = u ? u.uid : '';
  const all = Object.values(offersMap);
  const inList = all.filter(o => o.toUid === me), outList = all.filter(o => o.fromUid === me);
  const orders = all.filter(o => o.status === 'accepted' || o.status === 'signed').sort((a, b) => (b.updatedAt || b.at || 0) - (a.updatedAt || a.at || 0));
  const list = (offersTab === 'in' ? inList : outList).sort((a, b) => (b.updatedAt || b.at || 0) - (a.updatedAt || a.at || 0));
  const prices = inList.filter(o => o.kind === 'price' && o.price > 0).map(o => o.price);
  const avg = prices.length ? Math.round(prices.reduce((a, b) => a + b, 0) / prices.length) : 0;
  const waiting = all.filter(offersMyTurn).length;
  const stat = (label, val) => `<div class="ofp-stat"><b>${val}</b><small>${label}</small></div>`;
  const row = o => {
    const mine = o.fromUid === me;
    const other = mine ? (o.toName || 'משתמש') : (o.fromName || 'אורח');
    const otherUid = mine ? o.toUid : o.fromUid;
    const st = OFFER_ST[o.status] || OFFER_ST.pending;
    const when = typeof rdTimeAgo === 'function' ? rdTimeAgo(o.updatedAt || o.at) : '';
    const myTurn = offersMyTurn(o);
    const hist = Array.isArray(o.history) ? o.history.slice(-6) : [];
    const priceTxt = o.price ? `₪${Number(o.price).toLocaleString('he-IL')}${o.kind === 'loan' ? (o.priceUnit ? ' ' + o.priceUnit : '') : ''}` : '';
    const sub = [priceTxt, o.title || '', o.kind === 'loan' ? 'השאלה' : ''].filter(Boolean).join(' · ');
    const lastNote = hist.length ? (hist[hist.length - 1].note || '') : (o.note || '');
    const ic = {
      no: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.6" stroke-linecap="round"><path d="M6 6l12 12M18 6 6 18"/></svg>',
      deal: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M4 7h11M4 7l3-3M4 7l3 3"/><path d="M20 17H9M20 17l-3-3M20 17l-3 3"/></svg>',
      ok: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.8" stroke-linecap="round" stroke-linejoin="round"><path d="M5 12.5l4.5 4.5L19 7.5"/></svg>'
    };
    return `<div class="ofc${myTurn ? ' turn' : ''}">
      <span class="ofc-av" style="--av:${typeof forumAvColor === 'function' ? forumAvColor({ uid: otherUid, name: other }) : '#555'}" ${otherUid ? `onclick="openUserPage('${artEsc(otherUid)}','${artEsc(other)}')"` : ''}>${escHtml(String(other).trim().charAt(0) || '?')}</span>
      <div class="ofc-main" ${o.itemId ? `onclick="closeSidePanel('ofp-panel'); photoOpenDetail('${artEsc(o.itemId)}')"` : ''}>
        <b class="ofc-name">${escHtml(other)}</b>
        <span class="ofc-sub">${escHtml(sub)}</span>
        <span class="ofc-st"><i class="${st.cls}"></i>${myTurn ? 'הצעה ממתינה לתשובה שלך' : escHtml(st.label)}${when ? ' · ' + escHtml(when) : ''}${lastNote ? ' · ' + escHtml(lastNote) : ''}</span>
      </div>
      <div class="ofc-btns">
        ${myTurn ? `<button type="button" class="ofc-b no" onclick="offerDecide('${artEsc(o.id)}','rejected')" title="דחייה" aria-label="דחייה">${ic.no}</button>
        <button type="button" class="ofc-b deal" onclick="offerCounter('${artEsc(o.id)}')" title="משא ומתן — שינוי מחיר או סעיפים" aria-label="משא ומתן">${ic.deal}</button>
        <button type="button" class="ofc-b ok" onclick="offerDecide('${artEsc(o.id)}','accepted')" title="אישור" aria-label="אישור">${ic.ok}</button>`
        : (otherUid ? `<button type="button" class="ofc-b msg" onclick="dmStartWith('${artEsc(otherUid)}', '${artEsc(other)}', '')" title="הודעה" aria-label="הודעה"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M21 12a8 8 0 0 1-11.6 7.1L4 20l1-4.6A8 8 0 1 1 21 12z"/></svg></button>` : '')}
      </div>
    </div>`;
  };
  return `<div class="ofp">
    <div class="ofp-stats">${stat('מחכות לתשובה שלי', waiting)}${stat('הצעות שקיבלתי', inList.length)}${stat('ממוצע הצעה', avg ? '₪' + avg.toLocaleString('he-IL') : '—')}</div>
    <nav class="pfg-tabs"><button type="button" class="pfg-tab${offersTab === 'in' ? ' on' : ''}" onclick="offersSetTab('in')"><b>${inList.length}</b> התקבלו</button><button type="button" class="pfg-tab${offersTab === 'out' ? ' on' : ''}" onclick="offersSetTab('out')"><b>${outList.length}</b> נשלחו</button><button type="button" class="pfg-tab${offersTab === 'orders' ? ' on' : ''}" onclick="offersSetTab('orders')"><b>${orders.length}</b> הזמנות</button></nav>
    ${offersTab === 'orders' ? `<div class="ofp-list">${orders.length ? orders.map(o => orderTrackHTML(o, me)).join('') : orderTrackHTML(null, me) + '<div class="pf-empty">עדיין אין הזמנות — הצעה שאושרה הופכת להזמנה עם מעקב משלוח</div>'}</div>` : `<div class="ofp-list">${list.length ? list.map(row).join('') : `${ofpDemoCardHTML()}<div class="pf-empty">${offersTab === 'in' ? 'עדיין לא קיבלת הצעות — פרסמו מוצר במוצרי גולשים' : 'עדיין לא שלחת הצעות'}</div>`}</div>`}
  </div>`;
}
function offersRerender() { const b = document.querySelector('#ofp-panel .fo-panel-body'); if (b) b.innerHTML = ofpListHTML(); }
function offersSetTab(t) { offersTab = t; offersRerender(); }
async function offerUpdate(id, status, price, note) {
  const u = auth.currentUser; const o = offersMap[id]; if (!u || !o) return;
  const name = (typeof liveChatUserName === 'function' && liveChatUserName()) || u.displayName || 'אורח';
  const now = Date.now();
  const hist = (Array.isArray(o.history) ? o.history.slice(-20) : []).concat([{ by: u.uid, name: String(name).slice(0, 60), action: status === 'counter' ? 'counter' : status, price: Number(price) || 0, note: String(note || '').slice(0, 300), at: now }]);
  const upd = { status, lastBy: u.uid, updatedAt: now, history: hist };
  if (status === 'counter') { if (price) upd.price = Number(price); upd.note = String(note || '').slice(0, 300); }
  try {
    await update(ref(db, `website/offers/${id}`), upd);
    const other = o.fromUid === u.uid ? o.toUid : o.fromUid, otherName = o.fromUid === u.uid ? o.toName : o.fromName;
    const msg = status === 'accepted' ? `✅ אישרתי את ההצעה על "${o.title}"${o.price ? ` — ₪${Number(o.price).toLocaleString('he-IL')}` : ''}`
      : status === 'rejected' ? `❌ דחיתי את ההצעה על "${o.title}"`
      : `🟡 הצעה נגדית על "${o.title}"${price ? `: ₪${Number(price).toLocaleString('he-IL')}` : ''}${note ? ` — ${note}` : ''}`;
    showCopyToast(status === 'accepted' ? 'ההצעה אושרה' : status === 'rejected' ? 'ההצעה נדחתה' : 'ההצעה הנגדית נשלחה');
    // עדכון גם בהודעה פרטית
    try {
      const convId = dmConvId(u.uid, other);
      await push(ref(db, `website/dms/${convId}/messages`), { from: u.uid, fromName: dmName(), text: msg.slice(0, 1000), timestamp: now });
      await update(ref(db, `website/user_dms/${u.uid}/${convId}`), { otherUid: other, otherName: otherName || '', lastText: msg.slice(0, 60), lastTime: now, unread: false });
      await update(ref(db, `website/user_dms/${other}/${convId}`), { otherUid: u.uid, otherName: dmName(), lastText: msg.slice(0, 60), lastTime: now, unread: true });
    } catch (e) {}
  } catch (e) { console.error(e); showCopyToast('לא הצלחנו לעדכן — נסו שוב'); }
}
function offerDecide(id, status) {
  const o = offersMap[id]; if (!o) return;
  if (status === 'rejected' && !confirm('לדחות את ההצעה?')) return;
  offerUpdate(id, status, o.price, '');
}
// שינוי: מחיר משלי, או שינוי סעיף (בהשאלה)
function offerCounter(id) {
  const o = offersMap[id]; if (!o) return;
  let m = document.getElementById('offer-modal'); if (m) m.remove();
  m = document.createElement('div'); m.id = 'offer-modal'; m.className = 'rp-modal';
  m.innerHTML = `<div class="rp-card" role="dialog" aria-label="הצעה נגדית">
      <div class="rp-head"><b>הצעה נגדית</b><button type="button" class="fo-panel-x" onclick="closePriceOffer()" aria-label="סגירה"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round"><path d="M18 6 6 18M6 6l12 12"/></svg></button></div>
      <div class="rp-item">${escHtml(o.title || '')}${o.price ? ` · עכשיו ₪${Number(o.price).toLocaleString('he-IL')}` : ''}</div>
      <label class="of-price"><span>₪</span><input id="counter-price" type="number" inputmode="numeric" min="0" value="${Number(o.price) || ''}" placeholder="המחיר שלך"></label>
      <textarea id="counter-note" class="rp-note" rows="3" maxlength="300" placeholder="${o.kind === 'loan' || /השאלה/.test(o.note || '') ? 'איזה סעיף לשנות? למשל: סעיף 3 — נזק באחריות משותפת' : 'הערה (לא חובה)'}"></textarea>
      <div class="rp-actions"><button type="button" class="pf-btn" onclick="closePriceOffer()">ביטול</button><button type="button" class="pf-btn rp-send" onclick="offerCounterSend('${artEsc(id)}')">שליחת הצעה נגדית</button></div>
    </div>`;
  m.addEventListener('click', e => { if (e.target === m) closePriceOffer(); });
  document.body.appendChild(m);
}
function offerCounterSend(id) {
  const price = Math.round(Number((document.getElementById('counter-price') || {}).value)) || 0;
  const note = String((document.getElementById('counter-note') || {}).value || '').trim();
  if (!price && !note) { showCopyToast('כתבו מחיר או שינוי'); return; }
  closePriceOffer();
  offerUpdate(id, 'counter', price, note);
}
async function openOffersPanel() {
  if (!auth.currentUser) { const ok = (typeof ensureGuestSignedIn === 'function') ? await ensureGuestSignedIn() : false; if (!ok) { openLiveChatLogin(); return; } }
  offersSubscribe();
  closeSidePanels('ofp-panel');
  openSidePanel('ofp-panel', 'הצעות', ofpListHTML(), '');
}
try { onAuthStateChanged(auth, u => { if (u) setTimeout(offersSubscribe, 300); }); } catch (e) {}
Object.assign(window, { openOffersPanel, offersSetTab, offerDecide, offerCounter, offerCounterSend });


// תפריט צד (מובייל): מספר העוקבים והנעקבים
async function mnavLoadCounts(uid) {
  try {
    const snap = await get(ref(db, `website/follow_counts/${uid}`));
    const v = snap.val() || {};
    const fmt = n => (Number(n) || 0).toLocaleString('he-IL');
    const a = document.getElementById('mnx-following'), b = document.getElementById('mnx-followers');
    if (a) a.textContent = fmt(v.following); if (b) b.textContent = fmt(v.followers);
  } catch (e) {}
}


// ============================================================
// שמירה בסגנון X: הודעה קטנה למעלה "נשמר בשמורים" + "הוספה לתיקייה"
// התיקיות נשמרות בדפדפן: saved_folders_{uid|guest} = { שם: [ids] }
// ============================================================
function savedFoldersKey() { const u = auth.currentUser; return u ? `saved_folders_${u.uid}` : 'guest_saved_folders'; }
function savedFolders() { try { return JSON.parse(localStorage.getItem(savedFoldersKey()) || '{}') || {}; } catch (e) { return {}; } }
function savedFoldersSet(f) { try { localStorage.setItem(savedFoldersKey(), JSON.stringify(f)); } catch (e) {} }
function saveToast(id, saved) {
  let t = document.getElementById('save-toast');
  if (t) t.remove();
  t = document.createElement('div');
  t.id = 'save-toast'; t.className = 'save-toast';
  t.innerHTML = `<div class="st-row"><svg viewBox="0 0 24 24" fill="${saved ? 'currentColor' : 'none'}" stroke="currentColor" stroke-width="2" stroke-linejoin="round"><path d="M19 21l-7-5-7 5V5a2 2 0 0 1 2-2h10a2 2 0 0 1 2 2z"/></svg><span>${saved ? 'נשמר בשמורים' : 'הוסר מהשמורים'}</span></div>
    ${saved ? `<button type="button" class="st-btn" onclick="openFolderPicker('${artEsc(id)}')">הוספה לתיקייה</button>` : ''}`;
  document.body.appendChild(t);
  requestAnimationFrame(() => t.classList.add('show'));
  clearTimeout(window.__saveToastT);
  window.__saveToastT = setTimeout(() => { t.classList.remove('show'); setTimeout(() => t.remove(), 300); }, saved ? 4200 : 2200);
}
function openFolderPicker(id) {
  const t = document.getElementById('save-toast'); if (t) t.remove();
  const f = savedFolders();
  let m = document.getElementById('folder-modal'); if (m) m.remove();
  m = document.createElement('div'); m.id = 'folder-modal'; m.className = 'rp-modal';
  const row = n => `<button type="button" class="fd-row${f[n].includes(id) ? ' on' : ''}" onclick="folderToggle('${artEsc(id)}','${artEsc(n)}')"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linejoin="round"><path d="M3 7a2 2 0 0 1 2-2h4l2 2h8a2 2 0 0 1 2 2v8a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2z"/></svg><span>${escHtml(n)}</span><small>${f[n].length}</small><i>${f[n].includes(id) ? '✓' : ''}</i></button>`;
  m.innerHTML = `<div class="rp-card" role="dialog" aria-label="הוספה לתיקייה">
      <div class="rp-head"><b>הוספה לתיקייה</b><button type="button" class="fo-panel-x" onclick="document.getElementById('folder-modal').remove()" aria-label="סגירה"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round"><path d="M18 6 6 18M6 6l12 12"/></svg></button></div>
      <div class="fd-list">${Object.keys(f).map(row).join('') || '<div class="rp-item">עדיין אין תיקיות — צרו את הראשונה</div>'}</div>
      <div class="fd-new"><input id="fd-new-name" maxlength="30" placeholder="שם לתיקייה חדשה"><button type="button" class="pf-btn rp-send" onclick="folderCreate('${artEsc(id)}')">יצירה</button></div>
    </div>`;
  m.addEventListener('click', e => { if (e.target === m) m.remove(); });
  document.body.appendChild(m);
}
function folderToggle(id, name) {
  const f = savedFolders(); if (!f[name]) return;
  f[name] = f[name].includes(id) ? f[name].filter(x => x !== id) : f[name].concat([id]);
  savedFoldersSet(f); openFolderPicker(id);
  showCopyToast(f[name].includes(id) ? `נוסף לתיקייה "${name}"` : `הוסר מהתיקייה "${name}"`);
}
function folderCreate(id) {
  const n = String((document.getElementById('fd-new-name') || {}).value || '').trim().slice(0, 30);
  if (!n) return;
  const f = savedFolders(); if (!f[n]) f[n] = [];
  if (id && !f[n].includes(id)) f[n].push(id);
  savedFoldersSet(f); openFolderPicker(id);
  showCopyToast(`נוסף לתיקייה "${n}"`);
}
function savedOpenFolder(n) { window.__savedFolder = n; openSavedModal(); }
Object.assign(window, { openFolderPicker, folderToggle, folderCreate, savedOpenFolder });


// ============================================================
// חיפוש בסגנון X: "חיפושים אחרונים" (אנשים + מילים), ומציאת משתמשים
// ============================================================
function ssRecentGet() { try { return JSON.parse(localStorage.getItem('ss_recent') || '[]') || []; } catch (e) { return []; } }
function ssRecentSet(a) { try { localStorage.setItem('ss_recent', JSON.stringify(a.slice(0, 12))); } catch (e) {} }
function ssRecentAdd(entry) {
  const a = ssRecentGet().filter(x => entry.uid ? x.uid !== entry.uid : (x.q || '').toLowerCase() !== String(entry.q || '').toLowerCase());
  a.unshift(entry); ssRecentSet(a);
}
function ssRecentClear() { ssRecentSet([]); siteSearchRender(''); }
function ssRecentHTML() {
  const a = ssRecentGet(); if (!a.length) return '';
  const users = a.filter(x => x.uid), words = a.filter(x => x.q);
  return `<div class="ss-recent">
    <div class="ss-recent-head"><b>חיפושים אחרונים</b><button type="button" class="ss-recent-clear" onclick="ssRecentClear()" aria-label="ניקוי">✕</button></div>
    ${users.length ? `<div class="ss-recent-users">${users.slice(0, 8).map(u => `<button type="button" class="ss-ru" onclick="ssOpenUser('${artEsc(u.uid)}','${artEsc(u.name || '')}')">${authorAvHTML({ authorId: u.uid, author: u.name || '' })}<b>${escHtml(u.name || '')}</b><small dir="ltr">@${escHtml(typeof profileHandle === 'function' ? profileHandle(u.name || '') : (u.name || ''))}</small></button>`).join('')}</div>` : ''}
    ${words.map(w => `<div class="ss-rw"><button type="button" class="ss-rw-text" onclick="ssUseQuery('${artEsc(w.q)}')">${escHtml(w.q)}</button><button type="button" class="ss-rw-fill" onclick="ssFillQuery('${artEsc(w.q)}')" aria-label="העתקה לשורת החיפוש"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><path d="M17 17 7 7M7 15V7h8"/></svg></button></div>`).join('')}
  </div>`;
}
function ssFillQuery(q) { const inp = document.getElementById('site-search-input'); if (inp) { inp.value = q; inp.focus(); } siteSearchRender(q); }
function ssUseQuery(q) { ssRecentAdd({ q }); ssFillQuery(q); }
function ssOpenUser(uid, name) { ssRecentAdd({ uid, name }); closeSiteSearch(); if (typeof openUserPage === 'function') openUserPage(uid, name); }
// משתמשים: מכל מי שהעלה תוכן, כתב בפורום או ש"אני עוקב/ת" אחריו
function ssFindUsers(q) {
  const map = {};
  const add = (uid, name, n) => {
    if (!uid || !name || !/^[A-Za-z0-9_-]{10,}$/.test(uid)) return;
    if (!map[uid]) map[uid] = { uid, name: String(name), n: 0 };
    map[uid].n += n || 0;
  };
  // כל התוכן מכל העמודים (תמונות, קומיקס, סיפורים, יד שניה…)
  try {
    ((typeof pages !== 'undefined' && Array.isArray(pages)) ? pages : []).forEach(pg => {
      String((pg && pg.content) || '').replace(/data-(?:photos|stories)-json="([^"]*)"/g, (m, enc) => {
        try { (JSON.parse(decodeURIComponent(enc)) || []).forEach(x => x && add(x.authorId, x.author, 1)); } catch (e) {}
        return m;
      });
    });
  } catch (e) {}
  try { Object.values((typeof forumTopics !== 'undefined' && forumTopics) || {}).forEach(m => Object.values(m || {}).forEach(t => { if (t && !t.anon) add(t.uid, t.name, 0); })); } catch (e) {}
  try { Object.entries((typeof followedUids !== 'undefined' && followedUids) || {}).forEach(([uid, v]) => add(uid, v && v.name, 0)); } catch (e) {}
  return Object.values(map).filter(u => u.name.toLowerCase().includes(q) || (typeof profileHandle === 'function' && profileHandle(u.name).toLowerCase().includes(q)))
    .sort((a, b) => b.n - a.n).slice(0, 6);
}
Object.assign(window, { ssRecentClear, ssFillQuery, ssUseQuery, ssOpenUser });


