// שיחה: צירוף תמונות — חלון "מצלמה · תמונות · קבצים" ותצוגה מקדימה לפני שליחה
// ============================================================
window.__dmAttach = [];
function dmOpenAttach() {
  let m = document.getElementById('dm-attach'); if (m) m.remove();
  m = document.createElement('div'); m.id = 'dm-attach'; m.className = 'att-sheet';
  const tile = (label, icon, accept, capture, multi) => `<label class="att-tile"><input type="file" accept="${accept}"${capture ? ' capture="environment"' : ''}${multi ? ' multiple' : ''} onchange="dmAttachFiles(this.files)"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round">${icon}</svg><span>${label}</span></label>`;
  m.innerHTML = `<div class="att-backdrop" onclick="dmCloseAttach()"></div>
    <div class="att-panel" role="dialog" aria-label="צירוף">
      <div class="att-grip"></div>
      <div class="att-head"><button type="button" class="att-x" onclick="dmCloseAttach()" aria-label="סגירה"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round"><path d="M18 6 6 18M6 6l12 12"/></svg></button><b>צירוף לשיחה</b><span></span></div>
      <div class="att-grid">
        ${tile('מצלמה', '<path d="M4 8h3l2-3h6l2 3h3a1 1 0 0 1 1 1v10a1 1 0 0 1-1 1H4a1 1 0 0 1-1-1V9a1 1 0 0 1 1-1z"/><circle cx="12" cy="13.5" r="3.5"/>', 'image/*', true, false)}
        ${tile('תמונות', '<rect x="3" y="4" width="18" height="16" rx="3"/><circle cx="9" cy="10" r="2"/><path d="M21 16l-5-5-9 9"/>', 'image/*', false, true)}
        ${tile('קבצים', '<path d="M14 3H6a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V9z"/><path d="M14 3v6h6M12 17v-6M9.5 13.5 12 11l2.5 2.5"/>', 'image/*', false, true)}
      </div>
    </div>`;
  document.body.appendChild(m);
  requestAnimationFrame(() => m.classList.add('show'));
}
function dmCloseAttach() { const m = document.getElementById('dm-attach'); if (m) { m.classList.remove('show'); setTimeout(() => m.remove(), 220); } }
async function dmAttachFiles(files) {
  dmCloseAttach();
  const list = [...(files || [])].filter(f => /^image\//.test(f.type)).slice(0, 6);
  for (const f of list) {
    try {
      const data = await artCompressImage(f, 1280, 0.78);
      if (data && data.length < 400000) window.__dmAttach.push(data);
      else if (data) showCopyToast('התמונה גדולה מדי');
    } catch (e) {}
  }
  dmRenderAttach();
  const i = document.getElementById('dm-input'); if (i) i.focus();
}
function dmRenderAttach() {
  const box = document.getElementById('dm-attach-prev'); if (!box) return;
  const a = window.__dmAttach || [];
  box.innerHTML = a.map((src, i) => `<span class="tg-prev"><img src="${src}" alt=""><button type="button" onclick="dmRemoveAttach(${i})" aria-label="הסרה">✕</button></span>`).join('');
  box.classList.toggle('on', a.length > 0);
}
function dmRemoveAttach(i) { (window.__dmAttach || []).splice(i, 1); dmRenderAttach(); }
function dmViewImg(src) {
  const v = document.createElement('div'); v.className = 'tg-viewer';
  v.innerHTML = `<img src="${src}" alt="">`; v.onclick = () => v.remove();
  document.body.appendChild(v);
}
Object.assign(window, { dmOpenAttach, dmCloseAttach, dmAttachFiles, dmRemoveAttach, dmViewImg });


// ============================================================
// עמוד הבית במחשב: עמודה מימין בסגנון X — את מי לעקוב · פורומים להצטרף · אתרים מומלצים
// ============================================================
function homeAsideHTML() {
  const u = auth.currentUser, me = u ? u.uid : '';
  try { if (typeof subscribeMyFollows === 'function') subscribeMyFollows(); } catch (e) {}
  // את מי לעקוב: מי שהעלה הכי הרבה תוכן ועוד לא עוקבים אחריו
  const map = {};
  try {
    ((typeof pages !== 'undefined' && Array.isArray(pages)) ? pages : []).forEach(pg => {
      String((pg && pg.content) || '').replace(/data-(?:photos|stories)-json="([^"]*)"/g, (m, enc) => {
        try { (JSON.parse(decodeURIComponent(enc)) || []).forEach(x => {
          if (!x || !x.authorId || !/^[A-Za-z0-9_-]{10,}$/.test(x.authorId) || x.authorId === me) return;
          if (!map[x.authorId]) map[x.authorId] = { uid: x.authorId, name: x.author || 'משתמש', n: 0, item: x };
          map[x.authorId].n++;
        }); } catch (e) {}
        return m;
      });
    });
  } catch (e) {}
  const who = Object.values(map).filter(p => !(typeof isFollowing === 'function' && isFollowing(p.uid))).sort((a, b) => b.n - a.n);
  const whoRow = p => {
    const admin = typeof isSiteAdminAuthor === 'function' && isSiteAdminAuthor(p.uid, p.name, p.item);
    const name = admin ? 'מנהל האתר' : p.name;
    const verified = admin || (typeof isUserVerified === 'function' && isUserVerified(p.uid, p.name));
    return `<div class="ha-row">
      <button type="button" class="ha-who" onclick="openUserPage('${artEsc(p.uid)}','${artEsc(name)}')">${authorAvHTML({ authorId: p.uid, author: name })}
        <span class="ha-txt"><b>${escHtml(name)}${verified ? verifiedSealHTML(15) : ''}</b><small dir="ltr">@${escHtml(typeof profileHandle === 'function' ? profileHandle(name) : name)}</small></span></button>
      <button type="button" class="ha-btn" onclick="homeAsideFollow(this, '${artEsc(p.uid)}', '${artEsc(name)}')">עקיבה</button>
    </div>`;
  };
  // פורומים להצטרף: הפעילים ביותר
  let forums = [];
  try {
    forums = (typeof forumCats === 'function' ? forumCats() : []).flatMap(c => c.forums).map(f => {
      const t = (typeof forumTopicsOf === 'function') ? forumTopicsOf(f.id) : [];
      return { f, n: t.reduce((a, x) => a + 1 + (Number(x.replies) || 0), 0) };
    }).sort((a, b) => b.n - a.n);
  } catch (e) {}
  const forumRow = ({ f, n }) => `<div class="ha-row">
      <span class="ha-who"><span class="ha-ic"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round"><path d="M21 12a8 8 0 0 1-11.6 7.1L4 20l1-4.6A8 8 0 1 1 21 12z"/></svg></span>
        <span class="ha-txt"><b>${escHtml(f.title)}</b><small>${n ? `${n} הודעות` : escHtml(f.sub || '')}</small></span></span>
      <button type="button" class="ha-btn" onclick="openForumsPanel(); setTimeout(() => forumOpen('${artEsc(f.id)}'), 120)">כניסה</button>
    </div>`;
  // אתרים מומלצים
  const sites = (typeof PROMOTED_SITES !== 'undefined' && Array.isArray(PROMOTED_SITES)) ? PROMOTED_SITES : [];
  const host = url => { try { return new URL(url).hostname.replace(/^www\./, ''); } catch (e) { return ''; } };
  const siteRow = st => `<div class="ha-row">
      <span class="ha-who"><span class="ha-ic site">${st.image ? `<img src="${escHtml(st.image)}" alt="">` : escHtml(st.icon || '🌐')}</span>
        <span class="ha-txt"><b>${escHtml(st.name || '')}</b><small dir="ltr">${escHtml(host(st.url))}</small></span></span>
      <a class="ha-btn" href="${escHtml(typeof safeUrl === 'function' ? safeUrl(st.url) : st.url)}" target="_blank" rel="noopener sponsored">כניסה</a>
    </div>`;
  let haHidden = []; try { haHidden = JSON.parse(localStorage.getItem('ha_hidden') || '[]') || []; } catch (e) {}
  const box = (title, rows, more) => (rows && !haHidden.includes(title)) ? `<section class="ha-box"><h3>${title}</h3><button type="button" class="ha-x" onclick="homeAsideHide(this, '${artEsc(title)}')" aria-label="הסתרה" title="הסתרה"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round"><path d="M6 6l12 12M18 6 6 18"/></svg></button>${rows}${more ? `<button type="button" class="ha-more" onclick="${more}">הצג עוד</button>` : ''}</section>` : '';
  return `<aside class="home-aside" aria-label="המלצות">
    ${(() => {
      const whoBox = box('את מי לעקוב', who.slice(0, 3).map(whoRow).join(''), "homeAsideMore('who')");
      const loginBox = homeAsideLoginHTML();
      if (!loginBox || !whoBox) return whoBox + loginBox;
      // אורח: שתי הלשוניות בתיבה אחת — "את מי לעקוב" / "התחברות"
      let tab = 'who'; try { tab = localStorage.getItem('ha_tab') === 'login' ? 'login' : 'who'; } catch (e) {}
      const strip = h => h.replace(/^\s*<section class="ha-box[^"]*">/, '').replace(/<\/section>\s*$/, '').replace(/<h3>[^<]*<\/h3>/, '');
      return `<section class="ha-box ha-tabbed" data-tab="${tab}">
        <nav class="pfg-tabs ha-tabs"><button type="button" class="pfg-tab${tab === 'who' ? ' on' : ''}" onclick="haSetTab(this, 'who')">את מי לעקוב</button><button type="button" class="pfg-tab${tab === 'login' ? ' on' : ''}" onclick="haSetTab(this, 'login')">התחברות</button></nav>
        <div class="ha-pane" data-pane="who">${strip(whoBox)}</div>
        <div class="ha-pane ha-login" data-pane="login">${strip(loginBox)}</div>
      </section>`;
    })()}
    ${box('פורומים להצטרף', forums.slice(0, 3).map(forumRow).join(''), 'openForumsPanel()')}
    ${box('אתרים מומלצים', sites.slice(0, 3).map(siteRow).join(''), sites.length > 3 ? "homeAsideMore('sites')" : '')}
    <div class="ha-foot"><a href="#" onclick="event.preventDefault(); openLegal('terms')">תנאי שימוש</a> · <a href="#" onclick="event.preventDefault(); openLegal('privacy')">פרטיות</a> · <a href="#" onclick="event.preventDefault(); openLegal('a11y')">נגישות</a></div>
  </aside>`;
}
async function homeAsideFollow(btn, uid, name) {
  await toggleFollow(uid, name, null);
  const on = typeof isFollowing === 'function' && isFollowing(uid);
  btn.textContent = on ? 'עוקב/ת' : 'עקיבה';
  btn.classList.toggle('on', on);
}
function homeAsideMore(kind) {
  const aside = document.querySelector('.home-aside'); if (!aside) return;
  if (kind === 'who') { openFeed(); return; }
  if (kind === 'sites') { const s = (PROMOTED_SITES || [])[0]; if (s) window.open(s.url, '_blank', 'noopener'); }
}
Object.assign(window, { homeAsideFollow, homeAsideMore });


