// עמוד פריט: "שיעניינו אותך" — ריבועים קטנים בשורה, מעל שורת הכפתורים (בגודל הכפתורים)
// ============================================================
function recMiniEnhance() {
  document.querySelectorAll('.art-rec-section:not([data-mini])').forEach(sec => {
    sec.dataset.mini = '1';
    const cards = [...sec.querySelectorAll('.art-rec-card')];
    const acts = sec.closest('.art-detail, .pd2, [class*="detail"]')?.querySelector('.pd2-topacts') || document.querySelector('.art-detail .pd2-topacts') || document.querySelector('.art-detail .story-article');
    if (!cards.length || !acts) return;
    const items = cards.map((c, i) => {
      const img = c.querySelector('img');
      const title = (c.querySelector('h4') || {}).textContent || '';
      return `<button type="button" class="rec-mini-item" data-i="${i}" title="${escHtml(title)}" aria-label="${escHtml(title)}">${img ? `<img src="${escHtml(img.getAttribute('src') || '')}" alt="" loading="lazy">` : ''}</button>`;
    }).join('');
    const strip = document.createElement('div');
    strip.className = 'rec-mini-wrap';
    strip.innerHTML = `<span class="rec-mini-label">הצעות</span><div class="rec-mini">${items}</div>`;
    strip.addEventListener('click', e => {
      const b = e.target.closest('.rec-mini-item'); if (!b) return;
      const c = cards[Number(b.dataset.i)]; if (c) c.click();
    });
    const host = acts.closest('.pd2-toprow') || acts.closest('.pd2-topend') || acts;
    const inner = host.closest('.art-detail-inner');
    // מובייל: ההצעות בתחתית העמוד; מחשב: מעל הכפתורים
    if (inner && window.matchMedia('(max-width: 900px)').matches) { strip.classList.add('rec-mini-bottom'); inner.appendChild(strip); }
    else host.parentNode.insertBefore(strip, host);
    sec.classList.add('rec-mini-src');
  });
  // מובייל: שורת היוצר (תמונה, שם, תאריך, דירוג וצפיות) מעל התמונה
  if (window.matchMedia('(max-width: 900px)').matches) {
    document.querySelectorAll('.art-detail :is(.pd2, .pshow):not([data-cr-up])').forEach(pd => {
      const cr = pd.querySelector('.pd2-info > .pd2-creator'), media = pd.querySelector(':scope > .pd2-media, :scope > .pshow-stage');
      if (!cr || !media) return;
      pd.dataset.crUp = '1';
      cr.classList.add('pd2-creator-up');
      pd.insertBefore(cr, media);
      // קומיקס: הממוזערות של העמודים — מיד מתחת לתמונה המוצגת
      const tiles = pd.querySelector('.comic-info .pshow-tiles'), frame = media.querySelector('.pshow-frame');
      if (tiles && frame) { tiles.classList.add('pshow-tiles-up'); frame.after(tiles); }
    });
  }
}
(function recMiniWatch() {
  let t = 0;
  const obs = new MutationObserver(() => { if (t) return; t = setTimeout(() => { t = 0; recMiniEnhance(); }, 60); });
  const start = () => obs.observe(document.body, { childList: true, subtree: true });
  if (document.body) start(); else document.addEventListener('DOMContentLoaded', start);
})();


